import {
  parsePresentationBoot,
  parsePresentationRequest,
  parsePresentationResponse,
} from '@frade/runtime-contracts'
import type {
  PresentationApi,
  PresentationRequest,
  PresentationOutcome,
  PresentationRecord,
} from '@frade/runtime-contracts'
/** A separate capability object. Bootstrap is cached data, never a renderer filesystem call. */
export function createPresentationApi(
  bootInput: unknown,
  invoke: (input: unknown) => Promise<unknown>,
  id: () => string,
): PresentationApi {
  const boot = parsePresentationBoot(bootInput)
  let acceptedGeneration = boot.durable.generation
  const request = async (input: unknown) => {
    const value: PresentationRequest = parsePresentationRequest(input)
    if (value.sessionId !== boot.sessionId) throw Error('UNAUTHORIZED_SESSION')
    return parsePresentationResponse(await invoke(value), value)
  }
  return Object.freeze({
    getBoot: () => parsePresentationBoot(boot),
    announceIntent: async (requestId: string) => {
      const response = (await request({
        version: 1,
        sessionId: boot.sessionId,
        requestId,
        operation: 'intent',
        payload: {},
      })) as { readonly generation: number }
      if (response.generation <= acceptedGeneration) throw Error('STALE_PRESENTATION_INTENT')
      acceptedGeneration = response.generation
      return response
    },
    persist: async (context, selection, expectedRevision) =>
      (await request({
        version: 1,
        sessionId: boot.sessionId,
        requestId: context.requestId,
        operation: 'persist',
        payload: { context, selection, expectedRevision },
      })) as PresentationOutcome,
    reconcile: async (context, lastPublished) =>
      (await request({
        version: 1,
        sessionId: boot.sessionId,
        requestId: context.requestId,
        operation: 'reconcile',
        payload: { context, lastPublished },
      })) as PresentationRecord,
    ready: async (bootRevision: number, rootRevision: number) => {
      if (bootRevision !== boot.bootRevision || rootRevision !== boot.snapshot.revision)
        throw Error('STALE_PRESENTATION_READY')
      await request({
        version: 1,
        sessionId: boot.sessionId,
        requestId: id(),
        operation: 'ready',
        payload: { bootRevision, rootRevision },
      })
    },
  } satisfies PresentationApi)
}

import { parsePresentationBoot } from '@frade/runtime-contracts'
import type { PresentationApi } from '@frade/runtime-contracts'
import { createThemeController, applyRootSnapshot } from '@frade/ui-workspace/design/theme'
import type { ThemeController } from '@frade/ui-workspace/design/theme'
/** Synchronous validated projection precedes createRoot; Main show requires a later paint handshake. */
export function bootstrapPresentation(
  api: PresentationApi,
  root: HTMLElement,
  options: { paint?: () => Promise<void>; media?: (query: string) => MediaQueryList } = {},
): { controller: ThemeController; ready(): Promise<void>; dispose(): void } {
  const boot = parsePresentationBoot(api.getBoot())
  const media = options.media ?? ((query: string) => window.matchMedia(query))
  const dark = media('(prefers-color-scheme: dark)'),
    contrast = media('(prefers-contrast: more)'),
    forced = media('(forced-colors: active)')
  const environment = () => ({
    colorScheme: dark.matches ? ('dark' as const) : ('light' as const),
    highContrast: contrast.matches,
    forcedColors: forced.matches,
  })
  applyRootSnapshot(root, boot.snapshot)
  const controller = createThemeController({
    sessionId: boot.sessionId,
    root,
    initialSnapshot: boot.snapshot,
    initialDurable: {
      revision: boot.durable.revision,
      generation: boot.durable.generation,
      transactionId: boot.durable.transactionId,
      selection: boot.durable.selection,
    },
    diagnostics: boot.diagnostics,
    environment: environment(),
    paint: options.paint,
    host: {
      announceIntent: (requestId) => api.announceIntent(requestId),
      persist: (context, selection, expectedRevision) =>
        api.persist(context, selection, expectedRevision),
      reconcile: (context, lastPublished) =>
        api.reconcile(context, { version: 1, ...lastPublished }),
    },
  })
  let disposed = false,
    acknowledged = false,
    environmentPending = false,
    readiness: Promise<void> | undefined
  const changed = () => {
    if (disposed) return
    if (!acknowledged) {
      environmentPending = true
      return
    }
    void controller.refreshEnvironment(environment())
  }
  for (const query of [dark, contrast, forced]) query.addEventListener('change', changed)
  return {
    controller,
    ready: () =>
      (readiness ??= (async () => {
        await controller.whenReady()
        if (disposed) throw Error('Presentation bootstrap disposed')
        await api.ready(boot.bootRevision, controller.state().snapshot.revision)
        acknowledged = true
        if (environmentPending) {
          environmentPending = false
          changed()
        }
      })()),
    dispose: () => {
      if (disposed) return
      disposed = true
      for (const query of [dark, contrast, forced]) query.removeEventListener('change', changed)
      controller.dispose()
    },
  }
}

import { lstat, readFile, open, rename, unlink, mkdir } from 'node:fs/promises'
import { isAbsolute, join, resolve, dirname } from 'node:path'
import {
  parsePresentationBoot,
  parsePresentationRecord,
  parsePresentationRequest,
  parsePresentationChoice,
  parsePresentationPhase,
  PRESENTATION_MAX_BYTES,
} from '@frade/runtime-contracts'
import { createThemeRegistry, BUILTIN_IDS } from '@frade/ui-workspace/design/theme/registry'
import { resolveTheme } from '@frade/ui-workspace/design/theme/resolver'
import { authorizedSender } from './security'
import type {
  PresentationRecord,
  PresentationBoot,
  PresentationChoice,
  PresentationPhase,
  PresentationRequest,
} from '@frade/runtime-contracts'
export interface PresentationFiles {
  read(path: string): Promise<string | undefined>
  stage(path: string, contents: string): Promise<void>
  rename(staged: string, target: string): Promise<void>
  remove(path: string): Promise<void>
}
export interface PresentationSender {
  readonly senderId: number
  readonly mainFrame: boolean
  readonly url: string
}
export interface SettingsOptions {
  readonly userData: string
  readonly sessionId: string
  readonly windowId: number
  readonly devUrl?: string
  readonly environment?: {
    readonly colorScheme?: 'light' | 'dark'
    readonly highContrast?: boolean
    readonly forcedColors?: boolean
  }
  readonly files?: PresentationFiles
  readonly onReady?: (bootRevision: number, rootRevision: number) => void
}
export type SettingsOutcome =
  | { readonly status: 'ACK'; readonly durable: PresentationRecord }
  | { readonly status: 'REFUSED' | 'UNKNOWN'; readonly message: string }
export interface PresentationSettings {
  initialize(): Promise<PresentationBoot>
  bootstrap(sender: PresentationSender): PresentationBoot
  announceIntent(requestId: string): Promise<{ generation: number }>
  persist(
    context: PresentationPhase,
    selection: PresentationChoice,
    expectedRevision: number,
  ): Promise<SettingsOutcome>
  reconcile(
    context: PresentationPhase,
    lastPublished: PresentationRecord,
  ): Promise<PresentationRecord>
  request(sender: PresentationSender, input: unknown): Promise<unknown>
}

const errorText = (error: unknown): string =>
  (error instanceof Error ? error.message : String(error)).slice(0, 480)
const missing = (error: unknown) =>
  !!error && typeof error === 'object' && (error as NodeJS.ErrnoException).code === 'ENOENT'
function defaultFiles(): PresentationFiles {
  return {
    read: async (path) => {
      try {
        const info = await lstat(path)
        if (!info.isFile() || info.isSymbolicLink() || info.size > PRESENTATION_MAX_BYTES)
          throw Error('Invalid bounded presentation settings file')
        const contents = await readFile(path, 'utf8')
        if (Buffer.byteLength(contents, 'utf8') > PRESENTATION_MAX_BYTES)
          throw Error('Oversized presentation settings file')
        return contents
      } catch (error) {
        if (missing(error)) return undefined
        throw error
      }
    },
    stage: async (path, contents) => {
      await mkdir(dirname(path), { recursive: true })
      const file = await open(path, 'wx', 0o600)
      try {
        await file.writeFile(contents, 'utf8')
        await file.sync()
      } finally {
        await file.close()
      }
    },
    rename: async (staged, target) => {
      await rename(staged, target)
    },
    remove: async (path) => {
      try {
        const info = await lstat(path)
        if (info.isSymbolicLink() || !info.isFile()) throw Error('Unsafe presentation staged file')
        await unlink(path)
      } catch (error) {
        if (!missing(error)) throw error
      }
    },
  }
}
function sameSelection(a: PresentationChoice, b: PresentationChoice): boolean {
  return (
    a.mode === b.mode &&
    a.density === b.density &&
    a.preferred.light === b.preferred.light &&
    a.preferred.dark === b.preferred.dark &&
    a.preferred['high-contrast'] === b.preferred['high-contrast']
  )
}
function sameRecord(a: PresentationRecord, b: PresentationRecord): boolean {
  return (
    a.version === b.version &&
    a.revision === b.revision &&
    a.generation === b.generation &&
    a.transactionId === b.transactionId &&
    sameSelection(a.selection, b.selection)
  )
}
export function createPresentationSettings(options: SettingsOptions): PresentationSettings {
  if (!isAbsolute(options.userData)) throw Error('Presentation userData must be absolute')
  const root = resolve(options.userData),
    target = join(root, 'presentation-settings.json'),
    staged = join(root, 'presentation-settings.json.staged'),
    files = options.files ?? defaultFiles()
  const defaults = parsePresentationRecord({
    version: 1,
    revision: 0,
    generation: 0,
    transactionId: 'boot',
    selection: { mode: 'system', density: 'compact', preferred: { ...BUILTIN_IDS } },
  })
  let authoritative = defaults,
    origin: string | undefined,
    originProven = false,
    boot: PresentationBoot | undefined,
    initialization: Promise<PresentationBoot> | undefined
  let acceptedGeneration = 0,
    activeRequest = '',
    tail: Promise<unknown> = Promise.resolve(),
    maximumRevision = 0
  const known = new Map<number, PresentationRecord>(),
    candidates = new Map<number, PresentationRecord>()
  const remember = (map: Map<number, PresentationRecord>, value: PresentationRecord) => {
    map.set(value.revision, value)
    maximumRevision = Math.max(maximumRevision, value.revision)
    while (map.size > 64) map.delete(map.keys().next().value!)
  }
  const authorize = (sender: PresentationSender) => {
    if (
      !authorizedSender(
        sender.senderId,
        sender.mainFrame,
        sender.url,
        options.windowId,
        options.devUrl,
      )
    )
      throw Error('UNAUTHORIZED')
  }
  const queue = <T>(operation: () => Promise<T>): Promise<T> => {
    const result = tail.then(operation, operation)
    tail = result
    return result
  }
